<section class="admin-page-head"><div><p class="admin-kicker">PRECIOS M04</p><h1>Precios comerciales</h1><p>Importes MXN por variante, sucursal y lista. La ausencia nunca se presenta como cero.</p></div><div class="admin-head-actions"><?php if($capabilities['prices.create']??false):?><a class="admin-primary-button" href="/admin/prices/create<?= $branchId!==null?'?branch_id='.e($branchId):'' ?>">+ Nuevo precio</a><?php endif?><a class="admin-secondary-button" href="/admin/prices/calculate">Calcular</a></div></section>
<form class="admin-panel admin-filter-bar admin-filter-products" method="get"><label class="admin-field"><span>Buscar</span><input type="search" name="q" maxlength="120" value="<?= e($q) ?>" placeholder="Producto, variante o SKU"></label><label class="admin-field"><span>Sucursal</span><select name="branch_id"><option value="">Todas autorizadas</option><?php foreach($branches as$b):?><option value="<?= e($b['id']) ?>" <?= $branchId===(int)$b['id']?'selected':'' ?>><?= e($b['name']) ?></option><?php endforeach?></select></label><label class="admin-field"><span>Lista</span><select name="list_id"><option value="">Todas</option><?php foreach($lists as$l):?><option value="<?= e($l['id']) ?>" <?= $listId===(int)$l['id']?'selected':'' ?>><?= e($l['name']) ?></option><?php endforeach?></select></label><label class="admin-field"><span>Estado</span><select name="status"><option value="all">Todos</option><option value="active" <?= $status==='active'?'selected':'' ?>>Activos</option><option value="inactive" <?= $status==='inactive'?'selected':'' ?>>Inactivos</option></select></label><button class="admin-secondary-button">Aplicar</button></form>
<section class="admin-panel admin-table-panel"><?php if($page->items===[]):?><div class="admin-empty"><strong>Sin precios configurados</strong><span>Los productos pueden existir sin precio. No se mostrará $0.00 por ausencia.</span></div><?php else:?><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Variante</th><th>Sucursal / lista</th><th>Importe</th><th>Impuesto</th><th>Vigencia</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($page->items as$p):?><tr><td><strong><?= e($p['product_name']) ?></strong><small><?= e($p['sku'].' · '.$p['variant_name']) ?></small></td><td><?= e($p['branch_name']) ?><small><?= e($p['list_name']) ?></small></td><td><strong>$<?= e($p['amount']) ?> MXN</strong><small><?= (int)$p['tax_included']===1?'Impuesto incluido':'Impuesto no incluido' ?></small></td><td><?= e($p['tax_name']) ?></td><td><?= e($p['valid_from']) ?><small><?= e($p['valid_until']??'Sin fecha final') ?></small></td><td><span class="admin-status <?= (int)$p['is_active']===1?'is-active':'' ?>"><?= (int)$p['is_active']===1?'Activo':'Inactivo' ?></span></td><td class="admin-actions"><?php if($capabilities['prices.edit']??false):?><a class="admin-secondary-button" href="/admin/prices/edit?id=<?= e($p['id']) ?>">Editar</a><?php endif?><?php if($capabilities['prices.status']??false):?><form method="post" action="/admin/prices/status"><input type="hidden" name="_token" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= e($p['id']) ?>"><input type="hidden" name="lock_version" value="<?= e($p['lock_version']) ?>"><input type="hidden" name="active" value="<?= (int)$p['is_active']===1?'0':'1' ?>"><button class="admin-quiet-button" data-confirm="¿Confirmas el cambio de estado?"><?= (int)$p['is_active']===1?'Desactivar':'Activar' ?></button></form><?php endif?></td></tr><?php endforeach?></tbody></table></div><?php endif?></section>
